head.script:
scwin.fn_openPopup = function(useModalStack) {
	var rowJSON = {
		"poupObjectNm": "popup1"
	};
	var dataObj = {
		type: "json",
		data: rowJSON,
		name: "paramTest"
	};
	var options = {
		id: "popup1",
		type: "browserPopup",
		width: 300 + "px",
		height: 300 + "px",
		top: 100 + "px",
		left: 100 + "px",
		modal: true,
		onlyParam: true,
		style: "",
		resizable: true,
		status: false,
		menubar: false,
		scrollbars: false,
		title: false,
		useMaximize: true,
		dataObject: dataObj
	};
	if (useModalStack === false) {
		options.useModalStack = false;
	}
	$p.openPopup("", options);
};
scwin.trigger3_onclick = function(e) {
	scwin.fn_openPopup();
};
scwin.trigger4_onclick = function(e) {
	scwin.fn_openPopup(false);
};
